"code": "document.addEventListener('DOMContentLoaded', () => {
  const searchInput = document.getElementById('search');
  const chips = document.querySelectorAll('.chip');

  searchInput.value = state.searchQuery;
  chips.forEach(chip => {
    if (chip.dataset.category === state.activeCategory) chip.classList.add('chip-active');
    chip.addEventListener('click', () => {
      chips.forEach(c => c.classList.remove('chip-active'));
      chip.classList.add('chip-active');
      state.activeCategory = chip.dataset.category;
      renderMentors();
    });
  });

  searchInput.addEventListener('input', (e) => {
    state.searchQuery = e.target.value;
    renderMentors();
  });

  document.getElementById('mentor-list').addEventListener('click', (e) => {
    const favBtn = e.target.closest('.fav-btn');
    if (favBtn) {
      const card = favBtn.closest('.mentor-card');
      const isFav = favBtn.classList.toggle('active');
      favBtn.setAttribute('aria-label', isFav ? '마음에서 제거' : '마음에 넣기');
      return;
    }
    const card = e.target.closest('.mentor-card');
    if (card) alert('멘토 상세: ' + card.dataset.id);
  });
});"
}
